// Ajustes del flujo PR SAICA (app de conductores → SharePoint y correo)
const carpeta = 'https://grupotrimodos.sharepoint.com/:f:/s/GestionStinsa2/IgDhXF70TVa6RIjVPMcCoeveAb5bZPmGM4Ticd0VzvhCrRo?e=YFyck7';  // «Automatizacion»
return [{ json: {
  app: 'https://trimodos-conductores-pcsur-elo.vercel.app',   // dirección de la app (Vercel)
  codigoAcceso: '<<PONER EN N8N: el mismo que APP_ACCESS_CODE en Vercel>>',
  claveWebhook: '<<PONER EN N8N: la misma que PR_AVISOS_CLAVE en Vercel>>',
  buzonEnvio: 'agente.trafico@transargi.com',            // buzón de la credencial «Outlook Agente Trafico»
  paraPorDefecto: 'carmelomartinez@grupotrimodos.com',   // pruebas; luego sevilla@stinsa.com
  // el enlace de la carpeta en el formato de Graph («u!» + base64url)
  carpetaGraph: 'u!' + Buffer.from(carpeta).toString('base64').replace(/=+$/, '').replace(/\//g, '_').replace(/\+/g, '-'),
}}];

// Si viene de la app: se comprueba la clave y se usa lo que manda { evento, para, asunto, html, archivos }.
// Si es el resumen de la mañana: se pide a la app (novedades, datos pendientes, stock y Excel de registro).
const cfg = $('Configuración').first().json;
if ($('Desde la app').isExecuted) {
  const w = $('Desde la app').first().json;
  const clave = (w.headers || {})['x-clave'] || '';
  if (!cfg.claveWebhook || clave !== cfg.claveWebhook) throw new Error('Aviso PR con clave incorrecta: revisa PR_AVISOS_CLAVE en Vercel y «claveWebhook» en Configuración');
  return [{ json: w.body }];
}
let r;
try {
  r = await this.helpers.httpRequest({ method: 'GET', url: `${cfg.app}/api/pr/resumen`, json: true,
    headers: { 'X-Codigo-Acceso': cfg.codigoAcceso }, timeout: 60000 });
} catch (e) { throw new Error(`No se ha podido pedir el resumen a la app (${cfg.app}): ${e.message}`); }
return [{ json: r }];

// Un elemento por Excel que subir a SharePoint (con su dirección) y uno para el correo con las Excel adjuntas
// (la composición del tren viene con correo: false: solo se sube a SharePoint).
const cfg = $('Configuración').first().json;
const carpeta = $('Buscar la carpeta').first().json;
const d = $input.first().json;
const archivos = d.archivos || [];
const para = String(d.para || cfg.paraPorDefecto).split(/[;,]/).map(s => s.trim()).filter(Boolean);
const salida = archivos.map(a => ({
  json: { tipo: 'sharepoint', nombre: a.nombre,
    url: `https://graph.microsoft.com/v1.0/drives/${carpeta.parentReference.driveId}/items/${carpeta.id}:/${encodeURIComponent(a.nombre)}:/content` },
  binary: { archivo: { data: a.b64, mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', fileName: a.nombre } } }));
if (d.correo !== false) salida.push({ json: { tipo: 'correo', buzon: cfg.buzonEnvio, graph: { message: { subject: d.asunto || 'PR SAICA',
  body: { contentType: 'HTML', content: d.html || '' }, toRecipients: para.map(a => ({ emailAddress: { address: a } })),
  attachments: archivos.map(a => ({ '@odata.type': '#microsoft.graph.fileAttachment', name: a.nombre, contentBytes: a.b64 })) },
  saveToSentItems: true } } });
return salida;
